          runId: receipt.runId,
          activationId: receipt.activationId,
          generation: receipt.admittedGeneration,
          assignmentId: receipt.assignmentId,
          assignmentHash: receipt.assignmentHash,
          leaseId: receipt.leaseId,
          sessionId: receipt.sessionId,
